import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';

@Component({
  selector: 'app-sids-dashboard',
  templateUrl: './sids-dashboard.page.html',
  styleUrls: ['./sids-dashboard.page.scss'],
})
export class SidsDashboardPage implements OnInit {

  inspectionList: any = [];

  constructor(private router: Router,) { }

  ngOnInit() {
    this.getDashboard();
  }


  getDashboard() {
    this.inspectionList = [
      {
        id: 19,
        menu: 'Primary School',
        image: 'assets/icons/PMS.svg',
        url:'/tabs/primary-sids-school'
      },
      // {
      //   id: 22,
      //   menu: 'Higher Secondary',
      //   image: 'assets/icons/HSS.svg',
      //   url:'/tabs/sids-school'
      // }
    ];
  }

  goToSurvey(item){
    this.router.navigate([item.url]);
  }


  goToBack(){
    this.router.navigate(['/tabs/dashboard']);
  }

}
